all.css:
.pageBackground {
  --emberHot: #7fd66a;
  --emberCore: #eafff0;
  --emberMid: #2f7a45;
  --emberDeep: #08design;
  --emberDeep: #082116;
  overflow: hidden;
}

.emberScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 118%, color-mix(in srgb, var(--emberMid) 55%, transparent) 0%, transparent 62%),
    linear-gradient(to top, color-mix(in srgb, var(--emberDeep) 78%, transparent) 0%, transparent 58%);
}

.emberGlow {
  position: absolute;
  inset: auto -10% -30% -10%;
  height: 70%;
  background: radial-gradient(60% 100% at 50% 100%, color-mix(in srgb, var(--emberHot) 26%, transparent) 0%, color-mix(in srgb, var(--emberMid) 20%, transparent) 45%, transparent 75%);
  filter: blur(34px);
  opacity: .6;
}

/* Grass blades instead of a hot floor line: repeating conic slivers, blurred into a soft fringe. */
.emberFloor {
  position: absolute;
  inset: auto 0 0 0;
  height: 18%;
  background:
    repeating-linear-gradient(76deg,
      transparent 0 6px,
      color-mix(in srgb, var(--emberHot) 22%, transparent) 6px 7px,
      transparent 7px 13px),
    repeating-linear-gradient(104deg,
      transparent 0 9px,
      color-mix(in srgb, var(--emberMid) 32%, transparent) 9px 10px,
      transparent 10px 17px),
    linear-gradient(to top, color-mix(in srgb, var(--emberMid) 45%, transparent), transparent);
  mask-image: linear-gradient(to top, #000 0%, #000 30%, transparent 100%);
  filter: blur(2.5px);
  opacity: .8;
}

.emberChar {
  position: absolute;
  right: 0%;
  bottom: 12px;
  width: auto;
  height: 105%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .34;
  filter: drop-shadow(0 0 40px color-mix(in srgb, var(--emberHot) 30%, transparent));
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  animation: emberWaver 17s ease-in-out infinite;
}

/* Near layer: pinpricks, smaller and harder than embers, with a wide soft halo doing the glow. */
.emberSparks {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(1.5px 1.5px at 20% 30%, var(--emberCore), transparent 55%),
    radial-gradient(1.5px 1.5px at 70% 10%, var(--emberCore), transparent 55%),
    radial-gradient(1px 1px at 45% 75%, var(--emberHot), transparent 55%),
    radial-gradient(1.5px 1.5px at 90% 55%, var(--emberCore), transparent 55%),
    radial-gradient(1px 1px at 8% 62%, var(--emberHot), transparent 55%),
    radial-gradient(1px 1px at 58% 38%, var(--emberCore), transparent 55%);
  background-size: 180px 240px, 260px 320px, 220px 280px, 300px 380px, 240px 300px, 200px 260px;
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--emberHot) 70%, transparent));
  opacity: .85;
  animation: emberDriftNear 26s linear infinite, emberPulseNear 6.5s ease-in-out infinite;
  mask-image: linear-gradient(to top, #000 20%, transparent 85%);
}

/* Far layer: dimmer, slower, drifting sideways more than up: settled air, not updraft. */
.emberSparksFar {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(1px 1px at 35% 20%, var(--emberHot), transparent 55%),
    radial-gradient(1px 1px at 80% 65%, var(--emberCore), transparent 55%),
    radial-gradient(0.75px 0.75px at 55% 45%, var(--emberHot), transparent 55%),
    radial-gradient(1px 1px at 12% 85%, var(--emberCore), transparent 55%),
    radial-gradient(0.75px 0.75px at 92% 28%, var(--emberHot), transparent 55%);
  background-size: 140px 190px, 200px 250px, 170px 210px, 230px 290px, 160px 200px;
  filter: drop-shadow(0 0 3px color-mix(in srgb, var(--emberCore) 60%, transparent));
  opacity: .42;
  animation: emberDriftFar 48s linear infinite, emberPulseFar 9s ease-in-out infinite;
  mask-image: linear-gradient(to top, #000 15%, transparent 75%);
}

@keyframes emberWaver {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .34; }
  35%      { transform: translateY(-4px) rotate(.3deg) scale(1.003); opacity: .39; }
  70%      { transform: translateY(2px) rotate(-.2deg) scale(.999); opacity: .32; }
}

@keyframes emberDriftNear {
  to { background-position: 26px -240px, -38px -320px, 30px -280px, -24px -380px, 34px -300px, -30px -260px; }
}

@keyframes emberDriftFar {
  to { background-position: -22px -190px, 28px -250px, -30px -210px, 20px -290px, -26px -200px; }
}

@keyframes emberPulseNear {
  0%, 100% { opacity: .85; }
  50%      { opacity: .55; }
}

@keyframes emberPulseFar {
  0%, 100% { opacity: .42; }
  50%      { opacity: .26; }
}

@media (prefers-reduced-motion: reduce) {
  .emberChar, .emberSparks, .emberSparksFar { animation: none; }
}

