  background: radial-gradient(60% 100% at 50% 100%, color-mix(in srgb, var(--emberHot) 40%, transparent) 0%, color-mix(in srgb, var(--emberMid) 18%, transparent) 45%, transparent 75%);
  filter: blur(28px);
  opacity: .75;
}

.emberFloor {
  position: absolute;
  inset: auto 0 0 0;
  height: 14%;
  background: linear-gradient(to top, color-mix(in srgb, var(--emberHot) 30%, transparent), transparent);
  filter: blur(10px);
