  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
}

/* Near layer: bigger, brighter, faster. Inset top is negative so the tiles have room to scroll in
   from below the frame instead of popping at the edge. */
.emberSparks {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(2px 2px at 20% 30%, var(--emberCore), transparent 60%),
    radial-gradient(3px 3px at 70% 10%, var(--emberCore), transparent 60%),
    radial-gradient(2px 2px at 45% 75%, var(--emberHot), transparent 60%),
    radial-gradient(3px 3px at 90% 55%, var(--emberCore), transparent 60%),
    radial-gradient(2px 2px at 8% 62%, var(--emberHot), transparent 60%);
  background-size: 180px 240px, 260px 320px, 220px 280px, 300px 380px, 240px 300px;
  filter: drop-shadow(0 0 7px var(--emberHot));
  opacity: .9;
  animation: emberDriftNear 14s linear infinite;
  mask-image: linear-gradient(to top, #000 20%, transparent 85%);
}

/* Far layer: smaller, dimmer, slower: the parallax that keeps the loop from reading as one sheet. */
.emberSparksFar {
  position: absolute;
  inset: -50% 0 0 0;
  z-index: 3;
  background-image:
    radial-gradient(1.5px 1.5px at 35% 20%, var(--emberHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 80% 65%, var(--emberCore), transparent 60%),
    radial-gradient(1px 1px at 55% 45%, var(--emberHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 12% 85%, var(--emberHot), transparent 60%);
  background-size: 140px 190px, 200px 250px, 170px 210px, 230px 290px;
  filter: drop-shadow(0 0 4px var(--emberHot));
  opacity: .5;
  animation: emberDriftFar 26s linear infinite;
  mask-image: linear-gradient(to top, #000 15%, transparent 75%);
}

.emberChar {
  /* … keep everything above … */
  transform-origin: 60% 100%;
  animation: emberWaver 11s ease-in-out infinite;
}

@keyframes emberWaver {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .38; }
  35%      { transform: translateY(-6px) rotate(.4deg) scale(1.004); opacity: .44; }
  70%      { transform: translateY(3px) rotate(-.3deg) scale(.998); opacity: .36; }
}

@keyframes emberDriftNear {
  to { background-position: 12px -240px, -22px -320px, 16px -280px, -12px -380px, 20px -300px; }
}

@keyframes emberDriftFar {
  to { background-position: -8px -190px, 10px -250px, -14px -210px, 6px -290px; }
}

