/* Near layer: bigger, brighter, faster. Inset bottom is negative so the tiles have room to scroll in
   from above the frame instead of popping at the edge. */
.frostFlakes {
  position: absolute;
  inset: 0 0 -50% 0;
  z-index: 3;
  background-image:
    radial-gradient(2px 2px at 20% 30%, var(--iceCore), transparent 60%),
    radial-gradient(3px 3px at 70% 10%, #ffffff, transparent 60%),
    radial-gradient(2px 2px at 45% 75%, var(--iceHot), transparent 60%),
    radial-gradient(3px 3px at 90% 55%, var(--iceCore), transparent 60%),
    radial-gradient(2px 2px at 8% 62%, #cfeeff, transparent 60%);
  background-size: 180px 240px, 260px 320px, 220px 280px, 300px 380px, 240px 300px;
  filter: drop-shadow(0 0 7px var(--iceHot));
  opacity: .9;
  animation: frostFallNear 14s linear infinite;
  mask-image: linear-gradient(to bottom, #000 20%, transparent 85%);
}

/* Far layer: smaller, dimmer, slower: the parallax that keeps the loop from reading as one sheet. */
.frostFlakesFar {
  position: absolute;
  inset: 0 0 -50% 0;
  z-index: 3;
  background-image:
    radial-gradient(1.5px 1.5px at 35% 20%, #cfeeff, transparent 60%),
    radial-gradient(1.5px 1.5px at 80% 65%, var(--iceCore), transparent 60%),
    radial-gradient(1px 1px at 55% 45%, var(--iceHot), transparent 60%),
    radial-gradient(1.5px 1.5px at 12% 85%, #ffffff, transparent 60%);
  background-size: 140px 190px, 200px 250px, 170px 210px, 230px 290px;
  filter: drop-shadow(0 0 4px var(--iceHot));
  opacity: .5;
  animation: frostFallFar 26s linear infinite;
  mask-image: linear-gradient(to bottom, #000 15%, transparent 75%);
}

@keyframes frostSway {
  0%, 100% { transform: translateY(0) rotate(0deg) scale(1); opacity: .38; }
  35%      { transform: translateY(-4px) rotate(-.3deg) scale(1.003); opacity: .42; }
  70%      { transform: translateY(2px) rotate(.25deg) scale(.999); opacity: .35; }
}

@keyframes frostFallNear {
  to { background-position: -12px 240px, 22px 320px, -16px 280px, 12px 380px, -20px 300px; }
}

@keyframes frostFallFar {
  to { background-position: 8px 190px, -10px 250px, 14px 210px, -6px 290px; }
}

@media (prefers-reduced-motion: reduce) {
  .frostFlakes, .frostFlakesFar, .frostChar { animation: none; }
}

prompts.css:
.pageBackground {
  --sunHot: #ffc93d;
  --sunCore: #fff6d8;
  --sunMid: #f0a318;
  --sunDeep: #6b4a08;
  overflow: hidden;
}

/* glow + floor folded into the scene: 3 elements become 1 */
.sunScene {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(58% 80% at 62% -8%, color-mix(in srgb, var(--sunCore) 45%, transparent) 0%, color-mix(in srgb, var(--sunHot) 20%, transparent) 40%, transparent 72%),
    radial-gradient(120% 90% at 62% -18%, color-mix(in srgb, var(--sunHot) 55%, transparent) 0%, transparent 64%),
    linear-gradient(to bottom, color-mix(in srgb, var(--sunMid) 30%, transparent) 0%, transparent 45%),
    linear-gradient(to top, color-mix(in srgb, var(--sunHot) 18%, transparent) 0%, color-mix(in srgb, var(--sunDeep) 34%, transparent) 20%, transparent 55%);
}

.sunChar {
  position: absolute;
  right: 0;
  bottom: 12px;
  height: 100%;
  object-fit: contain;
  object-position: bottom right;
  opacity: .38;
  mask-image: linear-gradient(to top, transparent 0%, #000 14%, #000 100%);
  z-index: 1;
  transform-origin: 60% 100%;
  will-change: transform, opacity;
  animation: sunWaver 15s ease-in-out infinite;
}

/* one beam layer instead of two; soft-edged stops replace blur() */
.sunBeams {
  position: absolute;
  inset: -20% -30% -10% -30%;
  z-index: 3;
  transform: rotate(16deg);
  transform-origin: 70% 0%;
  background-image: repeating-linear-gradient(90deg,
    transparent 0 40px,
    color-mix(in srgb, var(--sunCore) 22%, transparent) 52px 68px,
    transparent 80px 126px,
    color-mix(in srgb, var(--sunHot) 14%, transparent) 134px 144px,
    transparent 152px 240px);
  opacity: .7;
  mask-image: linear-gradient(to bottom, #000 18%, transparent 88%);
}

/* the "far" parallax survives as a cheap child that slides on transform */
.sunBeams::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(90deg,
    transparent 0 80px,
    color-mix(in srgb, var(--sunCore) 12%, transparent) 92px 104px,
    transparent 116px 190px,
    color-mix(in srgb, var(--sunHot) 9%, transparent) 196px 204px,
    transparent 214px 320px);
  opacity: .5;
  will-change: transform;
  animation: sunSlide 34s linear infinite;
}

@keyframes sunWaver {
  0%, 100% { transform: translateY(0) rotate(0deg); opacity: .38; }
  35%      { transform: translateY(-5px) rotate(.3deg); opacity: .44; }
  70%      { transform: translateY(3px) rotate(-.2deg); opacity: .36; }
}

@keyframes sunSlide {
  to { transform: translateX(-320px); }
}

@media (prefers-reduced-motion: reduce) {
  .sunChar, .sunBeams::after { animation: none; }
}
